import { TreeEditor, Card } from "march/ui"

// pizza siparişi: malzemeleri ağaçta ekle, sil, değiştir; kart pizzayı malzeme emojileriyle çizer
const EMOJI: Record<string, string> = { mantar: "🍄", zeytin: "🫒", biber: "🌶️", domates: "🍅", mısır: "🌽", peynir: "🧀" }
type Pizza = { size?: string; toppings?: unknown[]; extraCheese?: boolean }

export function PizzaOrder() {
  let $order: unknown = { size: "orta", toppings: ["mantar", "zeytin", "biber"], extraCheese: true }
  const $p = ($order ?? {}) as Pizza
  const $face = [...($p.toppings ?? []).map((t) => EMOJI[String(t).toLowerCase()] ?? "❔"), ...($p.extraCheese ? ["🧀"] : [])].join(" ")
  return <div sx={{ flex: "col", gap: 2 }}>
    <Card m:theme="night">
      <div sx={{ flex: ["row", "center", "between"] }}>
        <span sx={{ text: "xl" }}>{`🍕 ${$face}`}</span>
        <span sx={{ text: "sm", color: "brand-orange" }}>{`${$p.size ?? "?"} boy`}</span>
      </div>
    </Card>
    <TreeEditor bind:value={$order} search={false} expand={2} label="Pizza siparişi" history
      schema={{ type: "object", properties: { size: { enum: ["küçük", "orta", "büyük"] }, toppings: { type: "array", items: { type: "string" }, maxItems: 5 } } }} />
  </div>
}

import { TreeEditor, Button, Badge, toast } from "march/ui"

// rol yetkileri: şema rolün adını ve her yetkinin true / false olmasını ister; onValidate sorun sayısını Kaydet'e taşır
const SCHEMA = {
  type: "object", required: ["role", "permissions"],
  properties: {
    role: { enum: ["admin", "editor", "viewer"] },
    permissions: { type: "object", additionalProperties: { type: "boolean" } },
    maxUploadMb: { type: "integer", minimum: 1, maximum: 500 },
  },
}

export function RolePermissions() {
  let $role: unknown = { role: "editor", permissions: { publish: true, delete: "maybe", invite: false }, maxUploadMb: 50 }
  let $problems = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <TreeEditor bind:value={$role} schema={SCHEMA} label="Editör rolü" onValidate={(e) => $problems = e.length} />
    <div sx={{ flex: ["row", "center", "between"] }}>
      <Badge tone={$problems ? "danger" : "success"}>{$problems ? `${$problems} sorun` : "Hazır"}</Badge>
      <Button disabled={$problems > 0} on:click={() => toast("Rol kaydedildi")}>Kaydet</Button>
    </div>
  </div>
}

import { TreeEditor, Card, Badge } from "march/ui"

// TreeEditor'ün bütün özellikleri: değer ve onChange, şema, ek denetim (validate yollarıyla), açık düzey, arama,
// geri alma, ağacın adı, onValidate, durum yazısı, tür rozetleri, satır eylemleri, kendi metinleri, sınıf, salt okunur
const SCHEMA = { type: "object", properties: { port: { type: "integer", minimum: 1024 }, tags: { type: "array", items: { type: "string" } } } }

export function TreeEditorLab() {
  let $v: unknown = { name: "api", port: 80, debug: false, tags: ["eu", "us"], note: "" }
  let $changes = 0
  let $problems = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Badge tone="neutral">{`${$changes} değişiklik · ${$problems} sorun`}</Badge>
    <TreeEditor value={$v} onChange={(x) => { $v = x; $changes++ }} class="lab-tree" label="Sunucu"
      schema={SCHEMA} validate={(x) => ((x as { name?: string })?.name === "api" ? [{ path: ["name"], message: "api adı eski" }] : [])}
      expand={2} search history onValidate={(e) => $problems = e.length} status typeBadges actions={["add", "delete"]}
      labels={{ root: "ayarlar", search: "Ayarlarda ara", valid: "Her şey yolunda", problems: (n) => `${n} düzeltilecek yer`,
        noMatches: "Bulunamadı", undo: "Geri al", redo: "Yinele", key: "Ad", valueName: (k) => `${k} değeri`, emptyText: "boş",
        items: (n) => `${n} öğe`, fields: (n) => `${n} alan`, addInside: "İçine ekle", addAfter: "Sonrasına ekle", duplicate: "Çoğalt",
        delete: "Sil", changeType: "Türü değiştir", typeOf: (k) => `Tür: ${k}`, kinds: { string: "metin", number: "sayı", boolean: "evet/hayır" } }} />
    <Card m:theme="night">
      <TreeEditor value={$v} readonly search={false} history={false} status={false} typeBadges={false} actions={false} expand={1} label="Salt okunur kopya" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TreeEditorLab } from "./TreeEditorLab.tsx"

// TreeEditorLab'in testleri: kaydedince Testler sekmesinde çalışır
test("şema ve validate sorunları sayılır, kendi metinlerle yazılır", async () => {
  const s = renderTest(() => <TreeEditorLab />)
  await s.flush()
  expect(s.get(".lab-tree .m-tre-status")?.textContent).toBe("2 düzeltilecek yer")
  expect(s.sees("0 değişiklik · 2 sorun")).toBe(true)
  expect(s.get(".lab-tree [role=tree]")?.getAttribute("aria-label")).toBe("Sunucu")
  expect(s.get(".lab-tree .m-tre-empty")?.textContent).toBe("boş")
})

test("yalnız listelenen satır eylemleri: ekle ve sil, çoğalt yok", async () => {
  const s = renderTest(() => <TreeEditorLab />)
  await s.flush()
  expect(s.get(".lab-tree .m-tre-add")).not.toBe(null)
  expect(s.get(".lab-tree .m-tre-dup")).toBe(null)
})

test("Sil bir alanı kaldırır, Geri al geri getirir", async () => {
  const s = renderTest(() => <TreeEditorLab />)
  await s.flush()
  const row = s.get('.lab-tree [data-ptr="/note"]')
  const del = [...(row?.querySelectorAll("button") ?? [])].find((b) => b.getAttribute("aria-label") === "Sil")
  await s.click(del!)
  expect(s.get('.lab-tree [data-ptr="/note"]')).toBe(null)
  expect(s.sees("1 değişiklik")).toBe(true)
  await s.click("Geri al")
  await s.flush()
  expect(s.get('.lab-tree [data-ptr="/note"]')).not.toBe(null)
})

test("kopya salt okunur: eylem yok, arama yok", async () => {
  const s = renderTest(() => <TreeEditorLab />)
  await s.flush()
  const copy = s.all("[role=tree]").find((t) => t.getAttribute("aria-label") === "Salt okunur kopya")
  expect(copy?.getAttribute("aria-readonly")).toBe("true")
  expect(s.all(".m-tre-actions").length).toBeGreaterThan(0)
  expect(s.all(".m-tre-search-input").length).toBe(1)
})
